public class TraceCallTreePlugin : AbstractDebuggerPlugin {
	TraceCallTreeProvider provider;

	private DebuggerCoordinates current;

	public TraceCallTreePlugin(PluginTool tool) : base(tool)
    {
	}

	/* @Override */
	protected void dispose() {
		tool.removeComponentProvider(provider);
		provider.dispose();
		base.dispose();
	}

	/* @Override */
	protected void init() {
		base.init();
		provider = new TraceCallTreeProvider(this);
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		base.processEvent(@event);
		switch (@event) {
			case TraceClosedPluginEvent evt: {
				Trace t = evt.getTrace();
				if ((current != null) && (current.getTrace() == t)) {
					current = null;
					provider.setCoordinates(null);
				}
				provider.traceClosed(evt.getTrace());
			}
			case TraceActivatedPluginEvent evt: {
				current = evt.getActiveCoordinates();
				provider.setCoordinates(current);
			}
			case OpenProgramPluginEvent evt: {
				provider.programOpened(evt.getProgram());
			}
			case CloseProgramPluginEvent evt: {
				provider.programClosed(evt.getProgram());
			}
			default: {
			}
		}
	}
}
